python
def wordSlipsBossReceipt(line, k):
    a=line
    out=[]
    length=0
    for c in a+' ':
        if c==' ':
            if length: out.append(length)
            length=0
        else: length+=1
    return sum((i+1)*x for i,x in enumerate(out))


